var spiele = new List<Spiel>
{
    new Spiel("Kart Racer", "Rennen", 40),
    new Spiel("Dungeon Quest", "Rollenspiel", 60),
    new Spiel("Pixel Farm", "Simulation", 20),
    new Spiel("Speed Rush", "Rennen", 30),
    new Spiel("Dragon Saga", "Rollenspiel", 50)
};

Console.WriteLine(spiele.Any(s => s.Preis > 55));
Console.WriteLine(spiele.All(s => s.Preis < 50));
// Ausgabe:
// True
// False

class Spiel
{
    public string Titel { get; }
    public string Genre { get; }
    public int Preis { get; }
    public Spiel(string t, string g, int p) { Titel = t; Genre = g; Preis = p; }
}

// spiele wie oben
Spiel rpg = spiele.First(s => s.Genre == "Rollenspiel");
Console.WriteLine(rpg.Titel);

Spiel puzzle = spiele.FirstOrDefault(s => s.Genre == "Puzzle");
if (puzzle == null)
{
    Console.WriteLine("Kein Puzzle-Spiel gefunden");
}
// Ausgabe:
// Dungeon Quest
// Kein Puzzle-Spiel gefunden

// spiele wie oben
int gesamt = spiele.Sum(s => s.Preis);
double schnitt = spiele.Average(s => s.Preis);
int teuerstes = spiele.Max(s => s.Preis);

Console.WriteLine($"Summe: {gesamt}");
Console.WriteLine($"Schnitt: {schnitt}");
Console.WriteLine($"Max: {teuerstes}");
// Ausgabe:
// Summe: 200
// Schnitt: 40
// Max: 60

// spiele wie oben
var proGenre = spiele
    .GroupBy(s => s.Genre)
    .Select(g => $"{g.Key}: {g.Count()} Stück, {g.Sum(s => s.Preis)} Euro")
    .OrderBy(text => text);

foreach (string zeile in proGenre)
{
    Console.WriteLine(zeile);
}
// Ausgabe:
// Rennen: 2 Stück, 70 Euro
// Rollenspiel: 2 Stück, 110 Euro
// Simulation: 1 Stück, 20 Euro

var zahlen = new List<int> { 1, 5, 9 };
var gross = zahlen.Where(z => z > 4);   // noch nichts berechnet!
var fest = zahlen.Where(z => z > 4).ToList();   // sofort berechnet

zahlen.Add(20);

Console.WriteLine(gross.Count());   // jetzt erst wird gefiltert
Console.WriteLine(fest.Count);
// Ausgabe:
// 3
// 2

